#!/usr/bin/env python3
"""Validate the canonical Incident Clarity scenario pack (stdlib only)."""

import json
import sys
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PACK = ROOT / "scenarios" / "v0.1" / "scenarios.json"


def fail(errors, message):
    errors.append(message)


def main():
    errors = []
    try:
        pack = json.loads(PACK.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        print(f"Cannot load {PACK}: {exc}", file=sys.stderr)
        return 1

    for key in ("schema_version", "pack_version", "policies", "scenarios"):
        if key not in pack:
            fail(errors, f"Missing top-level key: {key}")

    policies = pack.get("policies", [])
    scenarios = pack.get("scenarios", [])
    policy_ids = [p.get("id") for p in policies]
    scenario_ids = [s.get("id") for s in scenarios]

    for label, values in (("policy", policy_ids), ("scenario", scenario_ids)):
        duplicates = [value for value, n in Counter(values).items() if n > 1]
        if duplicates:
            fail(errors, f"Duplicate {label} IDs: {duplicates}")
        if None in values:
            fail(errors, f"A {label} is missing its ID")

    if pack.get("default_policy_id") not in policy_ids:
        fail(errors, "default_policy_id does not reference a policy")

    for policy in policies:
        for key in ("id", "label", "text", "rationale"):
            if not isinstance(policy.get(key), str) or not policy.get(key).strip():
                fail(errors, f"Policy {policy.get('id', '?')} needs nonempty {key}")

    pair_counts = Counter()
    required = (
        "id", "pair_id", "title", "lifecycle_stage", "contrast",
        "provisional_hypothesis", "facts",
    )
    for scenario in scenarios:
        sid = scenario.get("id", "?")
        for key in required:
            if key not in scenario:
                fail(errors, f"{sid}: missing {key}")
        facts = scenario.get("facts")
        if not isinstance(facts, list) or len(facts) < 3:
            fail(errors, f"{sid}: expected at least three atomic facts")
        elif any(not isinstance(fact, str) or not fact.strip() for fact in facts):
            fail(errors, f"{sid}: every fact must be a nonempty string")
        pair_counts[scenario.get("pair_id")] += 1

    for pair_id, count in sorted(pair_counts.items()):
        if count != 2:
            fail(errors, f"Pair {pair_id} has {count} scenarios; expected exactly 2")

    expected = [
        ROOT / "protocol" / "pilot-protocol.md",
        ROOT / "policy" / "fmir-summary.md",
        ROOT / "README.md",
    ]
    for path in expected:
        if not path.is_file():
            fail(errors, f"Missing required document: {path.relative_to(ROOT)}")

    if errors:
        print("Validation failed:", file=sys.stderr)
        for error in errors:
            print(f"- {error}", file=sys.stderr)
        return 1

    print(
        f"OK: pack {pack['pack_version']} — {len(scenarios)} scenarios, "
        f"{len(pair_counts)} pairs, {len(policies)} explicit research prompts."
    )
    print("Reminder: schema validity is not expert validation.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

